from hera.analysis import open_run,resolve_channels,sdh_onset
import numpy as np
for rid in [6,7]:
 r=open_run(f'data/{rid}'); ch={c.cid:c for c in resolve_channels(r.meta)}
 I=r.col('sr0_X')/ch['sr0'].gain; R=np.abs(r.col('sr1_X')/ch['sr1'].gain/I); B=r.col('magnet_field')
 print('RUN',rid,'R',np.min(R),np.max(R),'I nA',np.min(I)*1e9,np.max(I)*1e9,'T',np.min(r.col('T_sample')),np.max(r.col('T_sample')))
 for name in ['k_2400_tg_curr','k_2400_bg_curr','sr0_P','sr1_P']: print(name,np.quantile(r.col(name),[0,.5,1]))
 try: print(sdh_onset(R,B,r_full_scale=5000).summary())
 except Exception as e: print(type(e).__name__,str(e))
PY
